// TffGolden CASES : each line "bits before after flags"; prints "bits\tbefore\tafter\tflags\ttext"
import androidx.compose.remote.core.layout.MockRemoteContext; import androidx.compose.remote.core.operations.TextFromFloat; import java.nio.file.*; import java.util.*;
public class TextFromFloatGolden { public static void main(String[] a) throws Exception { MockRemoteContext c=new MockRemoteContext(); StringBuilder o=new StringBuilder(); for(String l:Files.readAllLines(Paths.get(a[0]))){ String[] p=l.split(" "); int bits=(int)Long.parseLong(p[0]); short b=Short.parseShort(p[1]),af=Short.parseShort(p[2]); int f=Integer.parseInt(p[3]); String s; try{ TextFromFloat t=new TextFromFloat(50,Float.intBitsToFloat(bits),b,af,f); t.apply(c); s=c.getText(50);}catch(Throwable e){s="!"+e.getClass().getSimpleName();} o.append(p[0]+"\t"+b+"\t"+af+"\t"+f+"\t["+s+"]\n"); } Files.writeString(Paths.get(a[1]),o.toString()); } }
